"""
SpencerWeb Patcher — Jalankan sekali untuk update sensitive_files.py
Usage: python patch_sensitive.py
"""
import base64, zlib, os

DATA = ""

# Decode dan tulis file
content = zlib.decompress(base64.b64decode(DATA))
target = os.path.join(os.path.dirname(os.path.abspath(__file__)), "scanner", "sensitive_files.py")
with open(target, "wb") as f:
    f.write(content)
print(f"✅ File written to: {target}")
print(f"   Size: {len(content)} bytes")

# Verify
with open(target, "r") as f:
    text = f.read()
if "LAYER 2: POST-SCAN PATTERN DETECTION" in text:
    print("✅ Verified: LAYER 2 code present!")
else:
    print("❌ ERROR: LAYER 2 code NOT found!")
